package util;

import java.util.*;

/** Small dependency-free JSON parser/writer for this coursework project. */
public final class Json {
    private Json() {}
    public static Object parse(String s) { Parser p = new Parser(s == null ? "" : s); Object v = p.value(); p.ws(); if (p.i < p.s.length()) throw new IllegalArgumentException("Unexpected JSON at position " + p.i); return v; }
    @SuppressWarnings("unchecked") public static Map<String,Object> object(Object o) { if (!(o instanceof Map)) throw new IllegalArgumentException("Expected JSON object"); return (Map<String,Object>)o; }
    @SuppressWarnings("unchecked") public static List<Object> array(Object o) { if (!(o instanceof List)) throw new IllegalArgumentException("Expected JSON array"); return (List<Object>)o; }
    public static String stringify(Object o) { StringBuilder b = new StringBuilder(); write(o,b); return b.toString(); }
    private static void write(Object o,StringBuilder b) {
        if (o == null) b.append("null"); else if (o instanceof String) { b.append('"'); for(char c:((String)o).toCharArray()){ switch(c){case '"':b.append("\\\"");break;case '\\':b.append("\\\\");break;case '\n':b.append("\\n");break;case '\r':b.append("\\r");break;case '\t':b.append("\\t");break;default: if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);} } b.append('"'); }
        else if(o instanceof Number || o instanceof Boolean) b.append(o);
        else if(o instanceof Map){b.append('{');boolean first=true;for(Object e0:((Map<?,?>)o).entrySet()){Map.Entry<?,?> e=(Map.Entry<?,?>)e0;if(!first)b.append(',');first=false;write(String.valueOf(e.getKey()),b);b.append(':');write(e.getValue(),b);}b.append('}');}
        else if(o instanceof Iterable){b.append('[');boolean first=true;for(Object x:(Iterable<?>)o){if(!first)b.append(',');first=false;write(x,b);}b.append(']');} else write(String.valueOf(o),b);
    }
    private static final class Parser { final String s; int i=0; Parser(String s){this.s=s;} void ws(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;} Object value(){ws();if(i>=s.length())throw new IllegalArgumentException("Empty JSON");char c=s.charAt(i);if(c=='{')return obj();if(c=='[')return arr();if(c=='"')return str();if(c=='t'&&word("true"))return true;if(c=='f'&&word("false"))return false;if(c=='n'&&word("null"))return null;return num();} boolean word(String w){if(s.startsWith(w,i)){i+=w.length();return true;}return false;} Map<String,Object> obj(){Map<String,Object> m=new LinkedHashMap<>();i++;ws();if(i<s.length()&&s.charAt(i)=='}'){i++;return m;}while(true){ws();String k=str();ws();if(i>=s.length()||s.charAt(i++)!=':')throw new IllegalArgumentException("Expected colon");m.put(k,value());ws();if(i>=s.length())throw new IllegalArgumentException("Unclosed object");char c=s.charAt(i++);if(c=='}')return m;if(c!=',')throw new IllegalArgumentException("Expected comma");}} List<Object> arr(){List<Object>a=new ArrayList<>();i++;ws();if(i<s.length()&&s.charAt(i)==']'){i++;return a;}while(true){a.add(value());ws();if(i>=s.length())throw new IllegalArgumentException("Unclosed array");char c=s.charAt(i++);if(c==']')return a;if(c!=',')throw new IllegalArgumentException("Expected comma");}} String str(){if(i>=s.length()||s.charAt(i++)!='"')throw new IllegalArgumentException("Expected string");StringBuilder b=new StringBuilder();while(i<s.length()){char c=s.charAt(i++);if(c=='"')return b.toString();if(c=='\\'){if(i>=s.length())break;char e=s.charAt(i++);switch(e){case '"':b.append('"');break;case '\\':b.append('\\');break;case '/':b.append('/');break;case 'b':b.append('\b');break;case 'f':b.append('\f');break;case 'n':b.append('\n');break;case 'r':b.append('\r');break;case 't':b.append('\t');break;case 'u':if(i+4>s.length())throw new IllegalArgumentException("Bad unicode");b.append((char)Integer.parseInt(s.substring(i,i+4),16));i+=4;break;default:throw new IllegalArgumentException("Bad escape");}}else b.append(c);}throw new IllegalArgumentException("Unclosed string");} Number num(){int start=i;if(i<s.length()&&s.charAt(i)=='-')i++;while(i<s.length()&&Character.isDigit(s.charAt(i)))i++;if(i<s.length()&&s.charAt(i)=='.'){i++;while(i<s.length()&&Character.isDigit(s.charAt(i)))i++;}String n=s.substring(start,i);try{if(n.contains("."))return Double.parseDouble(n);return Long.parseLong(n);}catch(Exception e){throw new IllegalArgumentException("Bad number: "+n);}} }
}
